from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class DeltaPlanActivationASMV1(SchemaObject):
    procedure_state = SchemaField(name="procedure_state")
    cm_plan_id = SchemaField(name="cm_plan_id")
    operation_id = SchemaField(name="id")
    force_reset = SchemaField(name="force_reset", not_null=True)
    auto_lock_cells = SchemaField(name="auto_lock_cells", not_null=True)
    reset_needed = SchemaField(name="reset_needed")
    locked_cells = SchemaField(name="locked_cells")
    status = SchemaField(name="status")
    links = SchemaField(name="links")
    error_message = SchemaField(name="error_message")

    def __init__(self, procedure_state, cm_plan_id, operation_id, force_reset, auto_lock_cells, reset_needed,
                 locked_cells, status, links, error_message):
        self.procedure_state = procedure_state
        self.cm_plan_id = cm_plan_id
        self.operation_id = operation_id
        self.force_reset = force_reset
        self.auto_lock_cells = auto_lock_cells
        self.reset_needed = reset_needed
        self.locked_cells = locked_cells
        self.status = status
        self.links = links
        self.error_message = error_message

        super(DeltaPlanActivationASMV1, self).__init__()
